def set_timezone(timezone):
  valid_timezones = subprocess.check_output('timedatectl list-timezones', shell=True, encoding='utf8').strip().split('\n')
  if timezone not in valid_timezones:
    cloudlog.error(f"Timezone not supported {timezone}")
    return

  cloudlog.debug(f"Setting timezone to {timezone}")
  try:
    if AGNOS:
      tzpath = os.path.join("/usr/share/zoneinfo/", timezone)
      subprocess.check_call(f'sudo su -c "ln -snf {tzpath} /data/etc/tmptime && \
                              mv /data/etc/tmptime /data/etc/localtime"', shell=True)
      subprocess.check_call(f'sudo su -c "echo \"{timezone}\" > /data/etc/timezone"', shell=True)
    else:
      subprocess.check_call(f'sudo timedatectl set-timezone {timezone}', shell=True)
  except subprocess.CalledProcessError:
    cloudlog.exception(f"Error setting timezone to {timezone}")

def to_timestamp(arg, freq=None, tzinfo=None):
    """ Attempts to convert arg to timestamp """
    if arg is None:
        return arg

    if type(arg) == float:
        # to do, do we want to support this, ie with fractional seconds?
        raise TypeError("Cannot convert a float to datetime")

    if isinstance(arg, basestring):
        try:
            arg = parser.parse(arg)
        except Exception:
            pass

    return lib.Timestamp(arg, offset=freq, tzinfo=tzinfo)

def to_timestamp(d, default_timezone=timezone.utc):
    if isinstance(d, datetime):
        if d.tzinfo is None:
            d = d.replace(tzinfo=default_timezone)
        return timedelta_seconds(d - EPOCH)
    return d

def datetime_to_UTC(datetime_object):
    # type: (datetime.datetime) -> datetime.datetime
    if is_timezone_aware(datetime_object):
        return datetime_object.astimezone(timezone.utc)
    return datetime_object.replace(tzinfo=timezone.utc)

