def _postprocess_chunks(self, chunks: List[str]) -> List[str]:
    """Post-process chunks."""
    new_chunks = []
    for doc in chunks:
        if doc.replace(" ", "") == "":
            continue
        new_chunks.append(doc)
    return new_chunks

